const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=[{id:1,name:'Tiong Bahru Bakery',lat:1.2847,lng:103.8307,collection:'Coffee & slow mornings',emoji:'🥐',note:'A croissant, a flat white, and absolutely no rush.',saved:true},{id:2,name:'Singapore Botanic Gardens',lat:1.3138,lng:103.8159,collection:'Little escapes',emoji:'🌿',note:'Bring a book. Find a patch of shade.',saved:true},{id:3,name:'National Gallery Singapore',lat:1.29,lng:103.8519,collection:'Art & inspiration',emoji:'🏛',note:'An afternoon for getting a little lost in art.',saved:true},{id:4,name:'Haji Lane',lat:1.3006,lng:103.859,collection:'Little escapes',emoji:'🌈',note:'Colourful corners and independent shops.',saved:true},{id:5,name:'Lau Pa Sat',lat:1.2805,lng:103.8505,collection:'Good food, good company',emoji:'🍜',note:'An evening food stop in the city.',saved:true},{id:6,name:'Gardens by the Bay',lat:1.2816,lng:103.8636,collection:'Little escapes',emoji:'🌳',note:'A green escape by the waterfront.',saved:false},{id:7,name:'Joo Chiat Road',lat:1.3115,lng:103.9014,collection:'Art & inspiration',emoji:'🏘',note:'Take the long way past the colourful shophouses.',saved:false}];
let data;try{data=JSON.parse(localStorage.getItem('pocket-atlas-v1'))}catch{}let places=data?.places||seed,collections=data?.collections||['Coffee & slow mornings','Little escapes','Art & inspiration','Good food, good company'],filter='All',tab='saved',selected=null,point=null;
const persist=()=>localStorage.setItem('pocket-atlas-v1',JSON.stringify({places,collections}));let toastTimer;function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',2500)}
const map=L.map('map',{zoomControl:false}).setView([1.303,103.845],13);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors',maxZoom:19}).addTo(map);L.control.zoom({position:'bottomright'}).addTo(map);const layer=L.layerGroup().addTo(map);
function visible(){const q=$('search').value.trim().toLowerCase();return places.filter(p=>(tab==='saved'?p.saved:!p.saved)&&(filter==='All'||p.collection===filter)&&(`${p.name} ${p.collection} ${p.note}`).toLowerCase().includes(q))}
function render(){const list=visible();$('collections').innerHTML=['All',...collections].map(c=>`<button class="chip ${filter===c?'active':''}" data-collection="${esc(c)}">${esc(c)}</button>`).join('');$('count').textContent=`${list.length} ${tab==='saved'?'SAVED':'DISCOVER'} ${list.length===1?'PLACE':'PLACES'}`;$('list').innerHTML=list.length?list.map(p=>`<button class="place ${selected===p.id?'selected':''}" data-place="${p.id}"><span class="emoji">${p.emoji}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.collection)}</small></span><span class="arrow">↗</span></button>`).join(''):'<p class="empty">No places here yet. Save a new place or try another search.</p>';layer.clearLayers();list.forEach(p=>{L.marker([p.lat,p.lng],{title:p.name,keyboard:true,icon:L.divIcon({className:'',html:`<div class="pin ${p.saved?'':'unsaved'}"><span>${p.emoji}</span></div>`,iconSize:[39,39],iconAnchor:[20,39]})}).addTo(layer).on('click',()=>show(p.id))});document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab))}
function show(id){const p=places.find(p=>p.id===id);selected=id;render();map.flyTo([p.lat,p.lng],15,{duration:.6});$('detail').hidden=false;$('detail').innerHTML=`<button class="close" id="closedetail" aria-label="Close place">×</button><span class="tag">${p.saved?'A place you love':'A new little discovery'}</span><h2>${p.emoji} ${esc(p.name)}</h2><p>Singapore · ${p.lat.toFixed(4)}° N, ${p.lng.toFixed(4)}° E</p><label for="moveto">Collection</label><select id="moveto">${collections.map(c=>`<option ${p.collection===c?'selected':''}>${esc(c)}</option>`).join('')}</select><label for="note">Your note</label><textarea id="note" maxlength="500" placeholder="What makes it special?">${esc(p.note)}</textarea><div class="actions"><button id="savechanges" class="primary">${p.saved?'Save changes':'＋ Save place'}</button><button id="remove">${p.saved?'Unsave':'Close'}</button></div>`;$('closedetail').onclick=closeDetail;$('savechanges').onclick=()=>{p.collection=$('moveto').value;p.note=$('note').value;p.saved=true;persist();tab='saved';filter='All';render();show(p.id);toast('Saved to your places')};$('remove').onclick=()=>{if(p.saved){p.saved=false;persist();toast('Removed from saved places')}closeDetail();render()}}
function closeDetail(){selected=null;$('detail').hidden=true;render()}
$('list').onclick=e=>{const b=e.target.closest('[data-place]');if(b)show(Number(b.dataset.place))};$('collections').onclick=e=>{const b=e.target.closest('[data-collection]');if(b){filter=b.dataset.collection;closeDetail()}};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;filter='All';closeDetail()});$('search').oninput=()=>{closeDetail()};$('fit').onclick=()=>{const list=visible();if(list.length)map.fitBounds(list.map(p=>[p.lat,p.lng]),{padding:[65,65],maxZoom:15});closeDetail()};
function openAdd(){closeDetail();$('addcollection').innerHTML=collections.map(c=>`<option>${esc(c)}</option>`).join('');$('adddialog').showModal()};$('add').onclick=()=>{point=null;openAdd()};map.on('click',e=>{point=e.latlng;openAdd()});$('cancel').onclick=()=>$('adddialog').close();$('addform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p=point||map.getCenter();places.push({id:Date.now(),name:f.get('name').trim()||'Untitled place',collection:f.get('collection'),note:f.get('note'),emoji:'📍',lat:p.lat,lng:p.lng,saved:true});persist();$('adddialog').close();e.target.reset();tab='saved';filter='All';$('search').value='';render();show(places.at(-1).id);toast('A new place to come back to')};$('newcollection').onclick=()=>$('coldialog').showModal();$('colcancel').onclick=()=>$('coldialog').close();$('colform').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;if(name==='All'||collections.some(c=>c.toLowerCase()===name.toLowerCase())){toast('That collection already exists');return}collections.push(name);persist();filter=name;tab='saved';$('coldialog').close();e.target.reset();closeDetail();toast('Collection created')};render();
